// Guest patch for the probe fixture: exercises every package feature. The recipe is
// generated by tools/xrgame/guest-patch/test-probe.py from the built probe.exe.

namespace {
constexpr xrg_u64 kAddCalls = 1; // counter
constexpr xrg_u64 kCounted = 1;  // log tag
} // namespace

extern "C" {
// Typed hook: the original plus a bound game function (probe_triple(1000) = 3000).
int patched_add(int a, int b) {
    xrg_sdk_counter(kAddCalls, a);
    return original_add(a, b) + bound_triple(1000);
}

// Typed hook whose trampoline relocates a call.
int patched_counted(void) {
    const int value = original_counted();
    xrg_sdk_log(kCounted, value);
    return value * 10;
}

// Typed hook whose trampoline relocates a RIP-relative load.
int patched_read(void) {
    return original_read() + 100;
}

// "before" site at probe_before's add: eax += *probe_value (5).
void before_add(XrgSiteContext* ctx) {
    ctx->gpr->rax = static_cast<xrg_u32>(ctx->gpr->rax + *bound_value);
}

// "replace" site instead of `imul eax, eax, 65536`: eax * 2.
void replace_imul(XrgSiteContext* ctx) {
    ctx->gpr->rax = static_cast<xrg_u32>(ctx->gpr->rax * 2);
}
}
